<div style="display:flex;justify-content:space-between;align-items:center"><h1>Posts</h1><a class="btn" href="/admin/posts/create">Create post</a></div>
<div class="card"><table><thead><tr><th>ID</th><th>Title</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($posts as $post): ?><tr><td><?= (int)$post['id'] ?></td><td><?= e($post['title']) ?></td><td><?= e($post['status']) ?></td><td><a class="btn" href="/admin/posts/<?= (int)$post['id'] ?>/edit">Edit</a><form method="post" action="/admin/posts/<?= (int)$post['id'] ?>" style="display:inline"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn danger" onclick="return confirm('Delete this post?')">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
